import type { ButtonHTMLAttributes, Ref } from 'react';
import { cx } from '@/utils/cx';

export type CloseButtonSize = '2xs' | 'xs' | 'sm' | 'md';

export type CloseButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label'> & {
  size?: CloseButtonSize;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

const glyphSizes: Record<CloseButtonSize, number> = { '2xs': 8, xs: 11, sm: 13, md: 17 };
const strokes: Record<CloseButtonSize, number> = { '2xs': 1.6, xs: 2, sm: 2, md: 2.5 };

export function CloseButton({ size = 'xs', className, type = 'button', ...props }: CloseButtonProps) {
  const glyph = glyphSizes[size];
  const inset = size === '2xs' ? 1.4 : 2;
  return (
    <button type={type} data-size={size} className={cx('ui-close-button', className)} {...props}>
      <svg width={glyph} height={glyph} viewBox={`0 0 ${glyph} ${glyph}`} fill="none" aria-hidden="true">
        <path d={`M${inset} ${inset}L${glyph - inset} ${glyph - inset}M${glyph - inset} ${inset}L${inset} ${glyph - inset}`} stroke="currentColor" strokeWidth={strokes[size]} strokeLinecap="round" />
      </svg>
    </button>
  );
}

'use client';

import type { ComponentProps, ReactNode } from 'react';
import { Dialog, DialogTrigger, Heading, OverlayArrow, Popover as AriaPopover, Pressable, type PopoverProps as AriaPopoverProps } from 'react-aria-components';
import { CloseButton } from '@/components/base/buttons/close-button';
import { cx } from '@/utils/cx';

export type PopoverProps = {
  trigger: ComponentProps<typeof Pressable>['children'];
  title?: string;
  children: ReactNode | ((options: { close: () => void }) => ReactNode);
  placement?: AriaPopoverProps['placement'];
  showArrow?: boolean;
  showCloseButton?: boolean;
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
  'aria-label'?: string;
};

export function Popover({ trigger, title, children, placement = 'bottom start', showArrow = false, showCloseButton = false, isOpen, defaultOpen, onOpenChange, className, 'aria-label': label }: PopoverProps) {
  return <DialogTrigger isOpen={isOpen} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
    <Pressable>{trigger}</Pressable>
    <AriaPopover className={cx('ui-popover', className)} placement={placement} offset={showArrow ? 10 : 6}>
      {({isExiting})=><>
      {showArrow && <OverlayArrow className="ui-popover__arrow"><svg width="12" height="8" viewBox="0 0 12 8" aria-hidden><path d="M0 0 6 6 12 0"/></svg></OverlayArrow>}
      <Dialog inert={isExiting} className="ui-popover__dialog" aria-label={title ? undefined : label ?? 'Additional information'}>{({ close }) => <>
        {(title || showCloseButton) && <header className="ui-popover__header">{title && <Heading slot="title">{title}</Heading>}{showCloseButton && <CloseButton aria-label="Close popover" size="xs" onClick={close}/>}</header>}
        <div className="ui-popover__body">{typeof children === 'function' ? children({ close }) : children}</div>
      </>}</Dialog>
      </>}
    </AriaPopover>
  </DialogTrigger>;
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});
